// singleStreamStore fails any read outside one stream. It is how
// TestReplayIsPure turns "replay does not consult siblings" from an assertion
// about the code into an assertion the test can actually make.
type singleStreamStore struct {
	eventsource.Store
	allowed string
}

func (s singleStreamStore) Read(ctx context.Context, streamID string, fromVersion int) ([]*eventsource.Event, error) {
	if streamID != s.allowed {
		return nil, fmt.Errorf("replay read stream %q; only %q is available", streamID, s.allowed)
	}
	return s.Store.Read(ctx, streamID, fromVersion)
}

func (s singleStreamStore) ReadAll(ctx context.Context, filter eventsource.EventFilter) ([]*eventsource.Event, error) {
	return nil, fmt.Errorf("replay called ReadAll; only stream %q is available", s.allowed)
}

